import {INSTRUMENTS} from './music.js';
import {SOUND_BANK_LIMITS,collectionForTrack,soundCompatible,normalizeSoundCollection,exportSoundFile,parseSoundFile,planSoundImport} from './sound-bank.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountSoundBankUI({bank,panel,track,getDraft,loadDraft,guard,toast,download}){
 let page=0,archived=false,compatibleOnly=true,busy=false,incoming=null,selected=new Set(),importPage=0,duplicates=false,request=0;const perPage=4;
 const usable=p=>soundCompatible(p.instrument,track.instrument)&&(p.sound!==null||p.instrument===track.instrument);
 const shownRows=()=>bank.list().filter(p=>p.archived===archived&&(!compatibleOnly||usable(p)));
 const live=()=>panel.isConnected&&document.querySelector('#modal')?.open&&document.querySelector('#sound-bank-panel')===panel;
 const query=s=>panel.querySelector(s),error=e=>{if(live())query('#sound-bank-error').textContent=e.message};
 const safe=(fn)=>async()=>{if(busy||!live())return;busy=true;panel.querySelectorAll('button').forEach(b=>b.disabled=true);try{guard();await fn();if(live()){guard();render()}}catch(e){error(e)}finally{busy=false;if(live())renderControls()}};
 const renderControls=()=>{if(live()){panel.querySelectorAll('button').forEach(b=>b.disabled=false);panel.querySelectorAll('[data-incompatible]').forEach(b=>b.disabled=true);if(query('#sound-import-confirm'))query('#sound-import-confirm').disabled=!selected.size||query('#sound-import-confirm').dataset.invalid==='true';if(query('#sound-bank-prev'))query('#sound-bank-prev').disabled=page===0;if(query('#sound-bank-next'))query('#sound-bank-next').disabled=(page+1)*perPage>=shownRows().length;if(query('#sound-import-prev'))query('#sound-import-prev').disabled=importPage===0;if(query('#sound-import-next'))query('#sound-import-next').disabled=(importPage+1)*perPage>=incoming.length}};
 function importView(){const selection=[...selected].sort((a,b)=>a-b);let report,message,invalid=false;try{report=planSoundImport(bank.list(),incoming,selection,{duplicates,now:0});message=`选择 ${selection.length} 项 · 新增 ${report.added} · 内容重复跳过 ${report.skipped}（含归档）`}catch(e){message=e.message;invalid=true}
  return `<div class="sound-import-preview"><h4>导入预览 · 不会应用到轨道</h4><p>完整文件已校验。默认按来源音源与参数去重；原始合成与默认自定义参数不是同一种音色。</p><div class="sound-bank-actions"><button id="sound-import-all" class="quiet">全选</button><button id="sound-import-none" class="quiet">全不选</button><button id="sound-import-cancel" class="quiet">取消导入</button></div>${incoming.slice(importPage*perPage,(importPage+1)*perPage).map((p,j)=>{const i=importPage*perPage+j;return `<label class="sound-import-row"><input type="checkbox" data-sound-import-index="${i}" ${selected.has(i)?'checked':''}><span><strong>${escape(p.name)}</strong><small>${escape(INSTRUMENTS[p.instrument].name)} · ${p.sound===null?'精确原始合成':'自定义参数'}</small></span></label>`}).join('')}<div class="sound-bank-actions"><button id="sound-import-prev" class="quiet">上一页音色</button><span>${importPage+1} / ${Math.ceil(incoming.length/perPage)}</span><button id="sound-import-next" class="quiet">下一页音色</button></div><label class="check-label"><input id="sound-import-duplicates" type="checkbox" ${duplicates?'checked':''}>内容相同也作为新收藏导入</label><p id="sound-import-report" role="status">${escape(message)}</p><button id="sound-import-confirm" class="accent" ${invalid?'data-invalid="true" disabled':''}>只加入收藏，不应用</button></div>`;
 }
 function render(){if(!live())return;const rows=shownRows();page=Math.max(0,Math.min(page,Math.ceil(rows.length/perPage)-1));panel.innerHTML=`<div class="sound-bank-intro"><strong>我的音色收藏</strong><p>保存的是这份草稿，不是工程音符。选收藏只放进草稿，仍须点下方“应用到此轨”。旋律自定义参数可跨旋律音源；原生多层沿用目标音源，鼓仅同种鼓。原始合成只能用于原音源。</p></div><div class="sound-bank-save"><input id="sound-collection-name" maxlength="60" aria-label="音色收藏名称" placeholder="例如：夜晚柔和电钢琴"><button id="sound-bank-save" class="accent">收藏当前草稿</button><button id="sound-draft-export" class="quiet">下载当前草稿</button></div><div class="sound-bank-actions"><button id="sound-bank-import" class="quiet">导入音色文件</button><button id="sound-bank-export" class="quiet">导出未归档收藏</button><button id="sound-bank-toggle" class="quiet">${archived?'回到收藏':'查看归档'}</button><button id="sound-bank-reload" class="quiet">重新读取收藏</button></div><label class="check-label"><input id="sound-bank-compatible" type="checkbox" ${compatibleOnly?'checked':''}>只看适用此音源</label><input id="sound-bank-file" type="file" accept=".sprout-sounds,.json,application/json" hidden><div id="sound-bank-error" role="status" class="export-progress">${bank.available?'':escape(bank.error||'收藏库不可用；草稿仍可下载')}</div>${incoming?importView():`<div class="sound-bank-list">${rows.slice(page*perPage,(page+1)*perPage).map(p=>{const compatible=usable(p);return `<article class="sound-bank-row" data-sound-collection="${p.id}"><strong>${escape(p.name)}</strong><small>${escape(INSTRUMENTS[p.instrument].name)} · ${p.sound===null?'精确原始合成':'自定义参数'}${compatible?'': ' · 不适用于当前音源'}</small><div class="sound-bank-actions">${archived?`<button class="quiet" data-sound-restore="${p.id}">恢复收藏</button>`:`<button class="accent" data-sound-load="${p.id}" ${compatible?'':'data-incompatible disabled'}>放入音色草稿</button><button class="quiet" data-sound-archive="${p.id}">归档收藏</button>`}<button class="quiet" data-sound-export="${p.id}">下载此音色</button><button class="quiet" data-sound-rename="${p.id}">改收藏名</button></div></article>`}).join('')||'<p>当前筛选下还没有音色。先收藏草稿，或取消适用筛选查看其他音源。</p>'}</div><div class="sound-bank-actions"><button id="sound-bank-prev" class="quiet">上一页收藏</button><span>${rows.length?page+1:0} / ${Math.ceil(rows.length/perPage)}</span><button id="sound-bank-next" class="quiet">下一页收藏</button></div>`}<div class="modal-notice">本浏览器 / 此网站共用 ${bank.entries.length} / ${SOUND_BANK_LIMITS.entries} 项（含归档），上限 256 KiB，无自动淘汰。归档可恢复、不释放容量；下载 .sprout-sounds 搬运。收藏 / 导入 / 改名不改歌曲或撤销栈，不是云库、采样或 VST 预设。音色参数用于 WAV，MIDI 不带它们。</div>`;
  const temporary=()=>{guard();return normalizeSoundCollection({id:'draft',name:query('#sound-collection-name').value.trim()||track.name+' 音色',instrument:track.instrument,sound:getDraft(),createdAt:Date.now(),archived:false})};
  query('#sound-bank-save').onclick=safe(async()=>{const p=temporary();await bank.save(p);toast('音色草稿已收藏，没有应用或播放。')});query('#sound-draft-export').onclick=()=>{try{const p=temporary();download(JSON.stringify(exportSoundFile([p]),null,2),'Sprout音色草稿.sprout-sounds','application/json');toast('音色草稿已下载，没有应用。')}catch(e){error(e)}};
  query('#sound-bank-export').onclick=()=>{try{download(JSON.stringify(exportSoundFile(bank.list().filter(p=>!p.archived)),null,2),'Sprout音色收藏.sprout-sounds','application/json')}catch(e){error(e)}};
  query('#sound-bank-compatible').onchange=e=>{compatibleOnly=e.target.checked;page=0;render()};query('#sound-bank-toggle').onclick=()=>{archived=!archived;page=0;incoming=null;render()};query('#sound-bank-reload').onclick=safe(async()=>{await bank.reload();incoming=null});
  query('#sound-bank-import').onclick=()=>query('#sound-bank-file').click();query('#sound-bank-file').onchange=async e=>{const file=e.target.files[0],at=++request;if(!file)return;try{guard();if(file.size>SOUND_BANK_LIMITS.bytes)throw Error('音色文件不能超过 256 KiB');const presets=parseSoundFile(await file.text());if(at!==request||!live())return;guard();incoming=presets;selected=new Set(presets.map((_,i)=>i));importPage=0;duplicates=false;render()}catch(e){if(at===request)error(e)}finally{e.target.value=''}};
  panel.querySelectorAll('[data-sound-load]').forEach(b=>b.onclick=()=>{try{guard();loadDraft(collectionForTrack(bank.get(b.dataset.soundLoad),track.instrument));toast('收藏已放进音色草稿，尚未应用到工程。')}catch(e){error(e)}});
  panel.querySelectorAll('[data-sound-archive],[data-sound-restore]').forEach(b=>b.onclick=safe(async()=>{const restore=!!b.dataset.soundRestore;await bank.archive(b.dataset.soundArchive||b.dataset.soundRestore,!restore);toast(restore?'音色收藏已恢复。':'音色已归档，可恢复；没有删除。')}));
  panel.querySelectorAll('[data-sound-export]').forEach(b=>b.onclick=()=>{try{download(JSON.stringify(exportSoundFile([bank.get(b.dataset.soundExport)]),null,2),'Sprout单份音色.sprout-sounds','application/json')}catch(e){error(e)}});
  panel.querySelectorAll('[data-sound-rename]').forEach(b=>b.onclick=()=>{const p=bank.get(b.dataset.soundRename),row=b.closest('article');row.innerHTML=`<label>收藏名称<input id="sound-rename-value" maxlength="60" value="${escape(p.name)}" aria-label="修改收藏名称"></label><div class="sound-bank-actions"><button class="accent" id="sound-rename-confirm">保存收藏名称</button><button class="quiet" id="sound-rename-cancel">取消改名</button></div>`;query('#sound-rename-cancel').onclick=render;query('#sound-rename-confirm').onclick=safe(async()=>{await bank.rename(p.id,query('#sound-rename-value').value)})});
  if(query('#sound-bank-prev')){query('#sound-bank-prev').onclick=()=>{page--;render()};query('#sound-bank-next').onclick=()=>{page++;render()}}
  if(incoming){query('#sound-import-all').onclick=()=>{selected=new Set(incoming.map((_,i)=>i));render()};query('#sound-import-none').onclick=()=>{selected.clear();render()};query('#sound-import-cancel').onclick=()=>{incoming=null;request++;render()};query('#sound-import-prev').onclick=()=>{importPage--;render()};query('#sound-import-next').onclick=()=>{importPage++;render()};query('#sound-import-duplicates').onchange=e=>{duplicates=e.target.checked;render()};panel.querySelectorAll('[data-sound-import-index]').forEach(c=>c.onchange=()=>{const i=+c.dataset.soundImportIndex;c.checked?selected.add(i):selected.delete(i);render()});query('#sound-import-confirm').onclick=safe(async()=>{const report=await bank.import(incoming,[...selected].sort((a,b)=>a-b),{duplicates});incoming=null;page=0;toast(`收藏新增 ${report.added} 项，重复跳过 ${report.skipped} 项；歌曲没有改变。`)})}renderControls();
 }
 render();const at=++request;bank.reload().then(()=>{if(at===request&&live())render()}).catch(e=>{if(at===request)error(e)});
}
